"use client";
/* Unicorn, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Unicorn(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("unicorn"); }, []);
  return React.createElement("piix-sprite", { "name": "unicorn", ...piixAttrs(props) });
}

export default Unicorn;
